import type { AudioEngine } from "../AudioEngine.ts";
import { PITCH_PULSE_SEC } from "../../timing/Timeline.ts";
import { FIELD_POSITIONS, applyEnvelope, noiseBurst, spatialPanner } from "./shared.ts";

/**
 * The windup — and the game's metronome.
 *
 * The delivery is three beats, spaced exactly one PITCH_PULSE_SEC apart:
 *
 *     thud ---- thud ---- THUD ---- [release] ---- plate
 *      1          2         3           4            5
 *
 * The release lands on beat 4 and a fastball crosses the plate on beat 5. Off-speed
 * pitches arrive *off* the beat, late by however much slower they are.
 *
 * On Rookie/Pro, `countableBeats` gives each rock a rising pitch staircase so a
 * blind player can hear "one, two, THREE" without relying on the visual strip.
 */

export const WINDUP_BEATS = 3;
export const WINDUP_SECONDS = PITCH_PULSE_SEC * WINDUP_BEATS;

export interface WindupOptions {
  intensity?: number;
  /** Rising tone per beat so the count is ear-readable. */
  countableBeats?: boolean;
}

export function playWindup(engine: AudioEngine, at: number, options: WindupOptions = {}): number {
  const intensity = options.intensity ?? 1;
  const countable = options.countableBeats === true;
  const { ctx } = engine;
  const panner = spatialPanner(ctx, FIELD_POSITIONS.mound);
  panner.connect(engine.busInput("field"));

  // Beat 3 is accented: the "and" before the release.
  for (let beat = 0; beat < WINDUP_BEATS; beat++) {
    const accent = beat === WINDUP_BEATS - 1;
    playPulse(engine, panner, at + beat * PITCH_PULSE_SEC, {
      level: accent ? intensity * 1.15 : intensity * 0.7,
      accent,
      beatIndex: beat,
      countable,
    });
  }

  const rustle = engine.noise.source("pink", { loop: true });
  const rustleFilter = ctx.createBiquadFilter();
  rustleFilter.type = "lowpass";
  rustleFilter.frequency.value = 620;
  const rustleGain = ctx.createGain();
  rustle.connect(rustleFilter);
  rustleFilter.connect(rustleGain);
  rustleGain.connect(panner);

  const rustleStart = at + PITCH_PULSE_SEC;
  const rustleEnd = applyEnvelope(rustleGain.gain, {
    at: rustleStart,
    attack: 0.45,
    hold: 0.25,
    decay: 0.2,
    peak: 0.14 * intensity,
    sustain: 0.85,
  });
  rustle.start(rustleStart, engine.noise.randomOffset(1.2));
  rustle.stop(rustleEnd + 0.05);

  const gruntAt = at + (WINDUP_BEATS - 1) * PITCH_PULSE_SEC;
  const grunt = ctx.createOscillator();
  grunt.type = "sawtooth";
  grunt.frequency.setValueAtTime(132, gruntAt);
  grunt.frequency.exponentialRampToValueAtTime(88, gruntAt + 0.22);

  const formant = ctx.createBiquadFilter();
  formant.type = "bandpass";
  formant.frequency.value = 520;
  formant.Q.value = 2.2;

  const gruntGain = ctx.createGain();
  grunt.connect(formant);
  formant.connect(gruntGain);
  gruntGain.connect(panner);

  const gruntEnd = applyEnvelope(gruntGain.gain, {
    at: gruntAt,
    attack: 0.03,
    hold: 0.08,
    decay: 0.16,
    peak: 0.48 * intensity,
    sustain: 0.7,
  });
  grunt.start(gruntAt);
  grunt.stop(gruntEnd + 0.05);

  return at + WINDUP_SECONDS;
}

interface PulseOpts {
  level: number;
  accent: boolean;
  beatIndex: number;
  countable: boolean;
}

/** Cleat scuff over a low body thump; optional rising tone for countable beats. */
function playPulse(engine: AudioEngine, destination: AudioNode, at: number, opts: PulseOpts): void {
  const { ctx } = engine;
  const { level, accent, beatIndex, countable } = opts;

  noiseBurst(engine, destination, {
    at,
    duration: accent ? 0.065 : 0.05,
    color: "white",
    frequency: accent ? 1450 : 1150,
    q: 1.2,
    peak: 0.55 * level,
    attack: 0.0015,
  });

  const body = ctx.createOscillator();
  body.type = "sine";
  // Countable mode: each beat sits a musical step higher so "1-2-3" is obvious.
  const baseHz = countable ? 110 + beatIndex * 36 : 150;
  body.frequency.setValueAtTime(baseHz, at);
  body.frequency.exponentialRampToValueAtTime(Math.max(60, baseHz * 0.52), at + 0.09);

  const gain = ctx.createGain();
  body.connect(gain);
  gain.connect(destination);

  const end = applyEnvelope(gain.gain, {
    at,
    attack: 0.003,
    decay: 0.1,
    peak: (accent ? 0.55 : 0.42) * level,
  });
  body.start(at);
  body.stop(end + 0.05);

  if (countable) {
    // Short pitched pip on top of the thud — clearer count than body alone.
    const pip = ctx.createOscillator();
    pip.type = "triangle";
    const pipHz = 420 + beatIndex * 110;
    pip.frequency.setValueAtTime(pipHz, at);
    pip.frequency.exponentialRampToValueAtTime(pipHz * 0.7, at + 0.05);
    const pipGain = ctx.createGain();
    pip.connect(pipGain);
    pipGain.connect(destination);
    applyEnvelope(pipGain.gain, {
      at,
      attack: 0.002,
      decay: 0.055,
      peak: (accent ? 0.32 : 0.22) * level,
    });
    pip.start(at);
    pip.stop(at + 0.08);
  }
}
