import type { ExcitementLevel } from "../audio/voices/crowd.ts";
import type { GameSnapshot } from "./GameState.ts";
import { runnersInScoringPosition } from "./Baserunners.ts";

/**
 * Leverage — how much this at-bat matters, and the thing that should actually be
 * driving the crowd, not a slider the player has to remember to move.
 *
 * This is a game-feel heuristic, not a sabermetric reconstruction of the real
 * Leverage Index — no play-by-play win-probability tables here, just the handful
 * of situational facts a broadcast crowd audibly reacts to:
 *
 *   - a close score matters more than a lopsided one
 *   - runners in scoring position matter more than an empty bases
 *   - two outs with runners on is do-or-die in a way one out isn't
 *   - the 9th inning (or extras) matters more than the 3rd, and the bottom half
 *     of a potential final inning — win-or-continue — matters most of all
 *
 * The output is unitless, roughly 0.15 (mop-up duty in a blowout) to 3.5
 * (bases loaded, two outs, tie game, bottom of the ninth). `excitementForLeverage`
 * maps that onto the crowd's 1-5 scale.
 */

const REGULATION_INNINGS = 9;
const BLOWOUT_MARGIN = 6;

export function computeLeverage(snapshot: GameSnapshot): number {
  if (snapshot.gameOver) return 0;

  const margin = Math.abs(snapshot.score.home - snapshot.score.away);
  if (margin >= BLOWOUT_MARGIN) return 0.15;
  const marginFactor = 1 / (1 + margin * 0.6);

  const runnerWeight =
    1 +
    (snapshot.bases.first ? 0.35 : 0) +
    (snapshot.bases.second ? 0.55 : 0) +
    (snapshot.bases.third ? 0.75 : 0);

  const outsWeight = snapshot.outs === 2 ? 1.25 : snapshot.outs === 1 ? 1.05 : 1.0;
  const doOrDieBoost = runnersInScoringPosition(snapshot.bases) && snapshot.outs === 2 ? 1.3 : 1;
  // A deep count adds a little of its own tension independent of outs and
  // runners — modest on purpose, since it is a secondary factor in a real
  // leverage index too, not a primary one.
  const countFactor = 1 + snapshot.strikes * 0.08;

  const raw = marginFactor * runnerWeight * outsWeight * doOrDieBoost * countFactor * lateInningFactor(snapshot);
  return clamp(raw, 0.15, 3.5);
}

function lateInningFactor(snapshot: GameSnapshot): number {
  if (snapshot.inning < 7) return 1;
  if (snapshot.inning < REGULATION_INNINGS) return 1.3;
  // The 9th inning or extras. The bottom half is win-or-continue for the home
  // team — the single highest-stakes moment in the sport — so it outweighs the
  // top half of the same inning, which is merely "very important".
  return snapshot.half === "bottom" ? 2.2 : 1.7;
}

/** Maps a leverage index onto the crowd's five excitement levels. */
export function excitementForLeverage(leverage: number): ExcitementLevel {
  if (leverage >= 2.4) return 5;
  if (leverage >= 1.6) return 4;
  if (leverage >= 1.0) return 3;
  if (leverage >= 0.5) return 2;
  return 1;
}

/** True when the situation is worth the colour man remarking on directly. */
export function isHighLeverage(leverage: number): boolean {
  return leverage >= 1.8;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
