import type { AudioEngine } from "../audio/AudioEngine.ts";
import type { SwingInput } from "../timing/SwingInput.ts";
import type { PitchSequencer } from "../timing/PitchSequencer.ts";
import { PROFILES } from "../game/PitchSelector.ts";
import { CONTACT_WINDOW_MS, PERFECT_WINDOW_MS } from "../timing/Timeline.ts";
import type { TimingBucket } from "../timing/SwingJudge.ts";

/**
 * Automated timing harness.
 *
 * This is the single most valuable test in the project, because it is the only one
 * that exercises the real thing: a real AudioContext, real scheduling, the real
 * ClockBridge, the real SwingInput arming path, and the real judge. Unit tests can
 * prove the arithmetic; only this can prove the arithmetic is being fed correctly.
 *
 * It works by asking the ClockBridge when the plate will be *heard*, then injecting
 * a swing stamped at exactly that instant plus a known offset. The judged delta
 * should come back equal to the offset. Any discrepancy is drift in the clock
 * correlation over the ~1.5 s of the pitch — which is precisely the failure mode
 * this whole design exists to prevent, and which nothing else would surface.
 *
 * Run it from the console after clicking Play Ball:
 *
 *     await timingHarness.run()
 *
 * A passing run shows every `error` under about a millisecond. Injected timestamps
 * are synthetic on purpose: routing through `setTimeout` would add 5–15 ms of timer
 * jitter and measure the browser's scheduler rather than this codebase.
 */

export interface HarnessDeps {
  engine: AudioEngine;
  input: SwingInput;
  sequencer: PitchSequencer;
  getCalibrationMs: () => number;
  /** Stop the game loop and resolve only once it has actually exited. */
  pause: () => Promise<void>;
}

export interface HarnessRow {
  intendedOffsetMs: number;
  judgedDeltaMs: number;
  /** judgedDelta - intendedOffset. Should be ~0. */
  errorMs: number;
  expectedBucket: TimingBucket;
  actualBucket: TimingBucket;
  pass: boolean;
}

const DEFAULT_OFFSETS = [0, -25, 25, -50, 50, -90, 90];

/** Tolerance on the round trip. Anything above this is a real defect. */
const ERROR_TOLERANCE_MS = 2;

export function installTimingHarness(deps: HarnessDeps): void {
  const harness = {
    run: (offsets: readonly number[] = DEFAULT_OFFSETS) => runTimingHarness(deps, offsets),
  };
  (globalThis as unknown as Record<string, unknown>)["timingHarness"] = harness;
}

export async function runTimingHarness(
  deps: HarnessDeps,
  offsets: readonly number[] = DEFAULT_OFFSETS,
): Promise<HarnessRow[]> {
  const { engine, input, sequencer, getCalibrationMs } = deps;

  await deps.pause();
  await waitUntil(() => !sequencer.isPitchInFlight);

  const rows: HarnessRow[] = [];

  for (const offset of offsets) {
    // Dead centre, so location can never downgrade the tier and the timing bucket
    // is the only thing under test.
    const location = { horizontal: 0, vertical: 0 };

    const result = await sequencer.throwPitch(PROFILES.fastball, location, {
      onScheduled: (timeline) => {
        engine.clock.sample();
        const perceivedPlateMs = engine.clock.audioToPerf(timeline.plateTime);
        // Add the calibration back in: the judge subtracts it, and here we want the
        // judged delta to equal the offset we asked for.
        input.injectSwing(perceivedPlateMs + offset + getCalibrationMs());
      },
    });

    const judgedDeltaMs = result.judgment.deltaMs;
    const expectedBucket = bucketFor(offset);
    rows.push({
      intendedOffsetMs: offset,
      judgedDeltaMs: round(judgedDeltaMs),
      errorMs: round(judgedDeltaMs - offset),
      expectedBucket,
      actualBucket: result.judgment.timing,
      pass: result.judgment.timing === expectedBucket && Math.abs(judgedDeltaMs - offset) <= ERROR_TOLERANCE_MS,
    });

    // Let the pitch finish sounding before the next one starts.
    await waitUntil(() => engine.currentTime > result.timeline.resolveTime + 0.6);
  }

  const failures = rows.filter((row) => !row.pass);
  // eslint-disable-next-line no-console
  console.table(rows);
  // eslint-disable-next-line no-console
  console.log(
    failures.length === 0
      ? `timing harness: ${rows.length}/${rows.length} passed`
      : `timing harness: ${failures.length} FAILED of ${rows.length}`,
  );
  return rows;
}

function bucketFor(offsetMs: number): TimingBucket {
  const magnitude = Math.abs(offsetMs);
  if (magnitude < PERFECT_WINDOW_MS) return "perfect";
  if (magnitude <= CONTACT_WINDOW_MS) return offsetMs < 0 ? "early" : "late";
  return "miss";
}

function round(value: number): number {
  return Math.round(value * 100) / 100;
}

function waitUntil(predicate: () => boolean): Promise<void> {
  return new Promise((resolve) => {
    if (predicate()) {
      resolve();
      return;
    }
    const poll = setInterval(() => {
      if (!predicate()) return;
      clearInterval(poll);
      resolve();
    }, 25);
  });
}
