/**
 * Session length / role-lock / practice mode — persisted gate choices.
 */

export type SessionLength = 3 | 6 | 9;
export type RoleLock = "both" | "bat" | "pitch";
export type SessionMode = "exhibition" | "practice";

export interface SessionOptions {
  mode: SessionMode;
  length: SessionLength;
  roleLock: RoleLock;
}

const STORAGE_KEY = "botn.sessionOptions";

const DEFAULTS: SessionOptions = {
  mode: "exhibition",
  length: 9,
  roleLock: "both",
};

export function isSessionLength(value: unknown): value is SessionLength {
  return value === 3 || value === 6 || value === 9;
}

export function isRoleLock(value: unknown): value is RoleLock {
  return value === "both" || value === "bat" || value === "pitch";
}

export function isSessionMode(value: unknown): value is SessionMode {
  return value === "exhibition" || value === "practice";
}

export function loadSessionOptions(): SessionOptions {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULTS };
    const parsed = JSON.parse(raw) as Partial<SessionOptions>;
    return {
      mode: isSessionMode(parsed.mode) ? parsed.mode : DEFAULTS.mode,
      length: isSessionLength(parsed.length) ? parsed.length : DEFAULTS.length,
      roleLock: isRoleLock(parsed.roleLock) ? parsed.roleLock : DEFAULTS.roleLock,
    };
  } catch {
    return { ...DEFAULTS };
  }
}

export function saveSessionOptions(options: SessionOptions): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(options));
  } catch {
    /* private browsing */
  }
}

export function describeSession(options: SessionOptions): string {
  if (options.mode === "practice") return "Practice cage — Rookie fastballs on the beat.";
  const role =
    options.roleLock === "bat"
      ? " batting only"
      : options.roleLock === "pitch"
        ? " pitching only"
        : "";
  return `${options.length}-inning exhibition${role}.`;
}
