/**
 * VoiceBackend — the seam between "what gets said" and "how it is produced".
 *
 * The live build ships `SpeechVoiceBackend`: Web Speech for intelligible words,
 * plus the on-screen radio log, with crowd ducking on the audio clock. Delivery
 * lines stay silent so they do not talk over the windup pulse.
 *
 * That indirection is the point. A `SampledVoiceBackend` that loads pre-rendered
 * fragment clips as AudioBuffers on the announcer/color buses implements this same
 * interface and drops in without the queue, the phrase tables, or the game loop
 * changing. `LogVoiceBackend` remains for silent/log-only sessions.
 *
 * Web Speech is outside the Web Audio graph — it cannot be AM-filtered — but it
 * is the asset-free path to words you can actually understand.
 */

export type Speaker = "announcer" | "color" | "umpire";

export interface Phrase {
  /**
   * Stable fragment identifier. Unused by the log backend; a sampled backend keys
   * its clip manifest off this, which is why phrase assembly emits it today.
   */
  id: string;
  text: string;
  speaker: Speaker;
  /** 0..1 delivery heat. Drives gain and playback rate on a sampled backend. */
  energy: number;
}

export interface SpeakHandle {
  /** How long this phrase occupies the voice bus. */
  durationSec: number;
  /** Withdraw the phrase if it hasn't been delivered yet. */
  cancel(): void;
}

export interface VoiceBackend {
  /** Deliver `phrase` at the given audio-clock time. */
  speak(phrase: Phrase, atContextTime: number): SpeakHandle;
  /** Predicted duration, used by the queue to lay out the next phrase. */
  estimateDuration(phrase: Phrase): number;
}

/**
 * Play-by-play is fast — around 3.8 words a second while the ball is live, faster
 * still when the announcer is excited. This was originally set to a conversational
 * 3.1, which made every call long enough that the booth fell steadily behind the
 * game. Short calls still need a beat of air around them, hence the floor.
 */
export function estimateSpokenSeconds(text: string, energy: number): number {
  const words = text.trim().split(/\s+/).filter(Boolean).length;
  const wordsPerSecond = 3.8 + energy * 1.2;
  return Math.max(0.5, words / wordsPerSecond);
}
