import { stampOf, type SwingInput } from "../timing/SwingInput.ts";

/**
 * Large thumb-zone Swing / Release control for phones.
 * Feeds the same SwingInput path as Space / background taps.
 */
export class ActionPad {
  private readonly button: HTMLButtonElement;
  private readonly input: SwingInput;
  private role: "bat" | "pitch" = "bat";

  constructor(button: HTMLButtonElement, input: SwingInput) {
    this.button = button;
    this.input = input;
    this.button.type = "button";
    this.button.classList.add("action-fab");
    this.button.setAttribute("data-timing-action", "true");
    this.button.addEventListener("pointerdown", this.onPointerDown);
    this.syncLabel();
  }

  setRole(role: "bat" | "pitch"): void {
    this.role = role;
    this.syncLabel();
  }

  setEnabled(enabled: boolean): void {
    this.button.disabled = !enabled;
    this.button.hidden = !enabled;
  }

  private syncLabel(): void {
    const label = this.role === "bat" ? "Swing" : "Release";
    this.button.textContent = label;
    this.button.setAttribute("aria-label", `${label} — tap or press Space`);
  }

  private readonly onPointerDown = (event: PointerEvent): void => {
    // Don't let the window pointer listener also see this (button is ignored anyway).
    event.preventDefault();
    event.stopPropagation();
    this.input.injectSwing(stampOf(event, () => performance.now()));
  };

  dispose(): void {
    this.button.removeEventListener("pointerdown", this.onPointerDown);
  }
}
