import type { AudioEngine } from "../AudioEngine.ts";

/**
 * Building blocks common to every synthesized voice.
 *
 * The listener stands at home plate facing the mound. Web Audio's default
 * orientation puts -Z in front of the listener, so distances out toward the
 * pitcher are negative Z and anything behind the plate (catcher, umpire) is
 * positive Z. Distances are in metres and roughly to scale, because the
 * inverse-distance rolloff only sounds right if the geometry is honest.
 */

export const FIELD_POSITIONS = {
  mound: { x: 0, y: 0.4, z: -18.4 },
  plate: { x: 0, y: 0.8, z: 0 },
  catcher: { x: 0, y: 0.3, z: 1.1 },
  umpire: { x: -0.4, y: 1.4, z: 2.0 },
} as const;

export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

/**
 * An HRTF panner at a fixed point on the field, ready to be connected.
 *
 * `refDistance` is set well out toward the mound rather than at the listener, and
 * this is a gameplay decision, not an acoustic one. Physically honest rolloff
 * (ref 1.6, falloff 0.55) puts the mound at 0.148 gain — which buried the windup
 * and the ball release 11–16 dB *under* the crowd bed. Those two sounds are the
 * batter's only advance warning that a pitch is coming, so burying them makes the
 * game unplayable no matter how correct the timing engine underneath is.
 *
 * A broadcast has mics all over the field anyway, so a near-flat mound is also
 * closer to what a radio listener actually hears than a distant one.
 */
export function spatialPanner(ctx: BaseAudioContext, at: Vec3): PannerNode {
  const panner = ctx.createPanner();
  panner.panningModel = "HRTF";
  panner.distanceModel = "inverse";
  panner.refDistance = 10;
  panner.maxDistance = 80;
  panner.rolloffFactor = 0.35;
  setPosition(panner, at);
  return panner;
}

/** Positions a panner, using AudioParams where available and the legacy setter otherwise. */
export function setPosition(panner: PannerNode, at: Vec3, when?: number): void {
  const legacy = panner as PannerNode & { setPosition?: (x: number, y: number, z: number) => void };
  if (panner.positionX) {
    const t = when ?? 0;
    if (when === undefined) {
      panner.positionX.value = at.x;
      panner.positionY.value = at.y;
      panner.positionZ.value = at.z;
    } else {
      panner.positionX.setValueAtTime(at.x, t);
      panner.positionY.setValueAtTime(at.y, t);
      panner.positionZ.setValueAtTime(at.z, t);
    }
    return;
  }
  legacy.setPosition?.(at.x, at.y, at.z);
}

export interface EnvelopeSpec {
  at: number;
  attack: number;
  decay: number;
  peak: number;
  /** Flat section between attack and decay. Defaults to 0. */
  hold?: number;
  /** Level held during `hold`, as a fraction of `peak`. Defaults to 1. */
  sustain?: number;
}

/**
 * A percussive AD/ADS envelope on a gain param.
 * Returns the time at which the envelope has finished.
 *
 * Ramps to a floor of 0.0001 rather than 0 because `exponentialRampToValueAtTime`
 * cannot reach zero, and exponential decay is what makes a transient read as a
 * physical impact instead of a synth blip.
 */
export function applyEnvelope(param: AudioParam, spec: EnvelopeSpec): number {
  const { at, attack, decay, peak } = spec;
  const hold = spec.hold ?? 0;
  const sustain = spec.sustain ?? 1;

  param.setValueAtTime(0.0001, at);
  param.exponentialRampToValueAtTime(Math.max(peak, 0.0002), at + attack);
  if (hold > 0) {
    param.exponentialRampToValueAtTime(Math.max(peak * sustain, 0.0002), at + attack + hold);
  }
  const end = at + attack + hold + decay;
  param.exponentialRampToValueAtTime(0.0001, end);
  return end;
}

export interface NoiseBurstSpec {
  at: number;
  duration: number;
  color?: "white" | "pink" | "brown";
  /** Bandpass centre. Omit for an unfiltered burst. */
  frequency?: number;
  q?: number;
  filterType?: BiquadFilterType;
  attack?: number;
  peak?: number;
  /** Playback rate; >1 shifts the noise brighter. */
  rate?: number;
}

/**
 * Fire a filtered noise grain into `destination`.
 * The node graph is disposable — it is garbage once the source has stopped.
 */
export function noiseBurst(engine: AudioEngine, destination: AudioNode, spec: NoiseBurstSpec): number {
  const { ctx, noise } = engine;
  const duration = spec.duration;
  const attack = spec.attack ?? 0.002;
  const decay = Math.max(duration - attack, 0.005);

  const source = noise.source(spec.color ?? "white", { playbackRate: spec.rate ?? 1 });
  const gain = ctx.createGain();

  let tail: AudioNode = gain;
  if (spec.frequency !== undefined) {
    const filter = ctx.createBiquadFilter();
    filter.type = spec.filterType ?? "bandpass";
    filter.frequency.value = spec.frequency;
    filter.Q.value = spec.q ?? 1;
    gain.connect(filter);
    tail = filter;
  }
  source.connect(gain);
  tail.connect(destination);

  const end = applyEnvelope(gain.gain, {
    at: spec.at,
    attack,
    decay,
    peak: spec.peak ?? 0.5,
  });

  source.start(spec.at, noise.randomOffset(duration + 0.1));
  source.stop(end + 0.05);
  return end;
}

/**
 * Sample a contour function into a curve suitable for `setValueCurveAtTime`.
 * `shape` receives a normalised 0..1 position and returns the parameter value.
 */
export function buildCurve(points: number, shape: (t: number) => number): Float32Array {
  const curve = new Float32Array(points);
  for (let i = 0; i < points; i++) {
    curve[i] = shape(i / (points - 1));
  }
  return curve;
}
